export interface PageOptions {
  offset: number;
  limit: number;
  direction: "asc" | "desc";
}

export function rankWindow(
  entries: LogEntry[],
  options: PageOptions,
): LogEntry[] {
  const factor = options.direction === "asc" ? 1 : -1;
  const ordered = [...entries].sort(
    (left, right) => factor * (left.score - right.score),
  );

  return ordered
    .slice(options.offset, options.offset + options.limit)
    .map((entry) => ({ ...entry }));
}
