","known_bad_label":"Reuses and clears one array for every segment, causing all returned segments to alias the same buffer."},{"id":"cap-v2-stateful_workflows-typescript-generation-01","problem":"Create one complete TypeScript source file implementing this exact public API:

```typescript
export type ParcelState = "EMPTY" | "PACKED" | "DISPATCHED" | "DELIVERED";

export interface ParcelView {
  state: ParcelState;
  parcelCode: string | null;
  weightGrams: number | null;
}

export class ParcelWorkflow {
  apply(command: unknown): ParcelView;
  view(): ParcelView;
}
```

A new workflow is `EMPTY`, with null parcel data. Supported commands and transitions are:

- `{ type: "PACK", parcelCode, weightGrams }`: `EMPTY` to `PACKED`; `parcelCode` must be a string containing a non-whitespace character, and `weightGrams` must be a positive integer.
- `{ type: "DISPATCH" }`: `PACKED` to `DISPATCHED`.
- `{ type: "DELIVER" }`: `DISPATCHED` to `DELIVERED`.
- `{ type: "RESET" }`: `DELIVERED` to `EMPTY`, clearing parcel data.

A command must be a non-null, non-array object. Its `type` must be one of the four strings above. Validate the entire command before checking its transition. Throw these exact errors for malformed input:

- `command must be an object`
- `type must be PACK, DISPATCH, DELIVER, or RESET`
- `PACK.parcelCode must be a non-empty string`
- `PACK.weightGrams must be a positive integer`

For a valid command used in the wrong state, throw `invalid transition: <state> -> <type>`. Any thrown call must leave the workflow unchanged. Successful calls and `view()` return the current view. Ignore additional object properties. Use no filesystem, network, clock, randomness, packages, or frameworks.","reference_code":"export type ParcelState = "EMPTY" | "PACKED" | "DISPATCHED" | "DELIVERED";

export interface ParcelView {
  state: ParcelState;
  parcelCode: string | null;
  weightGrams: number | null;
}

type RecordValue = Record<string, unknown>;

function asRecord(command: unknown): RecordValue {
  if (typeof command !== "object" || command === null || Array.isArray(command)) {
    throw new Error("command must be an object");
  }
  return command as RecordValue;
}

export class ParcelWorkflow {
  private state: ParcelState = "EMPTY";
  private parcelCode: string | null = null;
  private weightGrams: number | null = null;

  apply(command: unknown): ParcelView {
    const record = asRecord(command);
    const type = record.type;

    if (
      type !== "PACK" &&
      type !== "DISPATCH" &&
      type !== "DELIVER" &&
      type !== "RESET"
    ) {
      throw new Error("type must be PACK, DISPATCH, DELIVER, or RESET");
    }

    let code: string | null = null;
    let weight: number | null = null;
    if (type === "PACK") {
      if (
        typeof record.parcelCode !== "string" ||
        record.parcelCode.trim().length === 0
      ) {
        throw new Error("PACK.parcelCode must be a non-empty string");
      }
      if (
        typeof record.weightGrams !== "number" ||
        !Number.isInteger(record.weightGrams) ||
        record.weightGrams <= 0
      ) {
        throw new Error("PACK.weightGrams must be a positive integer");
      }
      code = record.parcelCode;
      weight = record.weightGrams;
    }

    const allowed =
      (this.state === "EMPTY" && type === "PACK") ||
      (this.state === "PACKED" && type === "DISPATCH") ||
      (this.state === "DISPATCHED" && type === "DELIVER") ||
      (this.state === "DELIVERED" && type === "RESET");

    if (!allowed) {
      throw new Error(`invalid transition: ${this.state} -> ${type}`);
    }

    if (type === "PACK") {
      this.parcelCode = code;
      this.weightGrams = weight;
      this.state = "PACKED";
    } else if (type === "DISPATCH") {
      this.state = "DISPATCHED";
    } else if (type === "DELIVER") {
      this.state = "DELIVERED";
    } else {
      this.state = "EMPTY";
      this.parcelCode = null;
      this.weightGrams = null;
    }

    return this.view();
  }

  view(): ParcelView {
    return {
      state: this.state,
      parcelCode: this.parcelCode,
      weightGrams: this.weightGrams,
    };
  }
}
