        throw new Error("DECIDE.note must be a non-empty string");
      }
      approved = Boolean(record.approved);
      note = record.note;
    }

    const allowed =
      (this.state === "IDLE" && type === "START") ||
      (this.state === "REVIEWING" && type === "DECIDE") ||
      ((this.state === "ACCEPTED" || this.state === "REJECTED") &&
        type === "CLEAR");

    if (!allowed) {
