}\\n  }\\n\\n  segments.push(current);\\n  return segments;\\n}\\n```\",\"reference_code\":\"export function splitOnSeparators(\\n  values: readonly number[],\\n  separator: number,\\n): number[][] {\\n  const segments: number[][] = [];\\n  let current: number[] = [];\\n\\n  for (const value of values) {\\n    if (value === separator) {\\n      segments.push(current);\\n      current = [];\\n    } else {\\n      current.push(value);\\n    }\\n  }\\n\\n  segments.push(current);\\n  return segments;\\n}\\n\",\"known_bad_code\":\"export function splitOnSeparators(\\n  values: readonly number[],\\n  separator: number,\\n): number[][] {\\n  const segments: number[][] = [];\\n  const current: number[] = [];\\n\\n  for (const value of values) {\\n    if (value === separator) {\\n      segments.push(current);\\n      current.length = 0;\\n    } else {\\n      current.push(value);\\n    }\\n  }\\n\\n  segments.push(current);\\n  return segments;\\n}\\n\",\"known_bad_label\":\"Reuses and clears one array for every segment, causing all returned segments to alias the same buffer.\"},{\"id\":\"cap-v2-stateful_workflows-typescript-generation-01\",\"problem\":\"Create one complete TypeScript source file implementing this exact public API:\\n\\n```typescript\\nexport type ParcelState = \\\"EMPTY\\\" | \\\"PACKED\\\" | \\\"DISPATCHED\\\" | \\\"DELIVERED\\\";\\n\\nexport interface ParcelView {\\n  state: ParcelState;\\n  parcelCode: string | null;\\n  weightGrams: number | null;\\n}\\n\\nexport class ParcelWorkflow {\\n  apply(command: unknown): ParcelView;\\n  view(): ParcelView;\\n}\\n```\\n\\nA new workflow is `EMPTY`, with null parcel data. Supported commands and transitions are:\\n\\n- `{ type: \\\"PACK\\\", parcelCode, weightGrams }`: `EMPTY` to `PACKED`; `parcelCode` must be a string containing a non-whitespace character, and `weightGrams` must be a positive integer.\\n- `{ type: \\\"DISPATCH\\\" }`: `PACKED` to `DISPATCHED`.\\n- `{ type: \\\"DELIVER\\\" }`: `DISPATCHED` to `DELIVERED`.\\n- `{ type: \\\"RESET\\\" }`: `DELIVERED` to `EMPTY`, clearing parcel data.\\n\\nA command must be a non-null, non-array object. Its `type` must be one of the four strings above. Validate the entire command before checking its transition. Throw these exact errors for malformed input:\\n\\n- `command must be an object`\\n- `type must be PACK, DISPATCH, DELIVER, or RESET`\\n- `PACK.parcelCode must be a non-empty string`\\n- `PACK.weightGrams must be a positive integer`\\n\\nFor a valid command used in the wrong state, throw `invalid transition: <state> -> <type>`. Any thrown call must leave the workflow unchanged. Successful calls and `view()` return the current view. Ignore additional object properties. Use no filesystem, network, clock, randomness, packages, or frameworks.\",\"reference_code\":\"export type ParcelState = \\\"EMPTY\\\" | \\\"PACKED\\\" | \\\"DISPATCHED\\\" | \\\"DELIVERED\\\";\\n\\nexport interface ParcelView {\\n  state: ParcelState;\\n  parcelCode: string | null;\\n  weightGrams: number | null;\\n}\\n\\ntype RecordValue = Record<string, unknown>;\\n\\nfunction asRecord(command: unknown): RecordValue {\\n  if (typeof command !== \\\"object\\\" || command === null || Array.isArray(command)) {\\n    throw new Error(\\\"command must be an object\\\");\\n  }\\n  return command as RecordValue;\\n}\\n\\nexport class ParcelWorkflow {\\n  private state: ParcelState = \\\"EMPTY\\\";\\n  private parcelCode: string | null = null;\\n  private weightGrams: number | null = null;\\n\\n  apply(command: unknown): ParcelView {\\n    const record = asRecord(command);\\n    const type = record.type;\\n\\n    if (\\n      type !== \\\"PACK\\\" &&\\n      type !== \\\"DISPATCH\\\" &&\\n      type !== \\\"DELIVER\\\" &&\\n      type !== \\\"RESET\\\"\\n    ) {\\n      throw new Error(\\\"type must be PACK, DISPATCH, DELIVER, or RESET\\\");\\n    }\\n\\n    let code: string | null = null;\\n    let weight: number | null = null;\\n    if (type === \\\"PACK\\\") {\\n      if (\\n        typeof record.parcelCode !== \\\"string\\\" ||\\n        record.parcelCode.trim().length === 0\\n      ) {\\n        throw new Error(\\\"PACK.parcelCode must be a non-empty string\\\");\\n      }\\n      if (\\n        typeof record.weightGrams !== \\\"number\\\" ||\\n        !Number.isInteger(record.weightGrams) ||\\n        record.weightGrams <= 0\\n      ) {\\n        throw new Error(\\\"PACK.weightGrams must be a positive integer\\\");\\n      }\\n      code = record.parcelCode;\\n      weight = record.weightGrams;\\n    }\\n\\n    const allowed =\\n      (this.state === \\\"EMPTY\\\" && type === \\\"PACK\\\") ||\\n      (this.state === \\\"PACKED\\\" && type === \\\"DISPATCH\\\") ||\\n      (this.state === \\\"DISPATCHED\\\" && type === \\\"DELIVER\\\") ||\\n      (this.state === \\\"DELIVERED\\\" && type === \\\"RESET\\\");\\n\\n    if (!allowed) {\\n      throw new Error(`invalid transition: ${this.state} -> ${type}`);\\n    }\\n\\n    if (type === \\\"PACK\\\") {\\n      this.parcelCode = code;\\n      this.weightGrams = weight;\\n      this.state = \\\"PACKED\\\";\\n    } else if (type === \\\"DISPATCH\\\") {\\n      this.state = \\\"DISPATCHED\\\";\\n    } else if (type === \\\"DELIVER\\\") {\\n      this.state = \\\"DELIVERED\\\";\\n    } else {\\n      this.state = \\\"EMPTY\\\";\\n      this.parcelCode = null;\\n      this.weightGrams = null;\\n    }\\n\\n    return this.view();\\n  }\\n\\n  view(): ParcelView {\\n    return {\\n      state: this.state,\\n      parcelCode: this.parcelCode,\\n      weightGrams: this.weightGrams,\\n    };\\n  }\\n}\\n\",\"known_bad_code\":\"export type ParcelState = \\\"EMPTY\\\" | \\\"PACKED\\\" | \\\"DISPATCHED\\\" | \\\"DELIVERED\\\";\\n\\nexport interface ParcelView {\\n  state: ParcelState;\\n  parcelCode: string | null;\\n  weightGrams: number | null;\\n}\\n\\ntype RecordValue = Record<string, unknown>;\\n\\nfunction asRecord(command: unknown): RecordValue {\\n  if (typeof command !== \\\"object\\\" || command === null || Array.isArray(command)) {\\n    throw new Error(\\\"command must be an object\\\");\\n  }\\n  return command as RecordValue;\\n}\\n\\nexport class ParcelWorkflow {\\n  private state: ParcelState = \\\"EMPTY\\\";\\n  private parcelCode: string | null = null;\\n  private weightGrams: number | null = null;\\n\\n  apply(command: unknown): ParcelView {\\n    const record = asRecord(command);\\n    const type = record.type;\\n\\n    if (\\n      type !== \\\"PACK\\\" &&\\n      type !== \\\"DISPATCH\\\" &&\\n      type !== \\\"DELIVER\\\" &&\\n      type !== \\\"RESET\\\"\\n    ) {\\n      throw new Error(\\\"type must be PACK, DISPATCH, DELIVER, or RESET\\\");\\n    }\\n\\n    let code: string | null = null;\\n    let weight: number | null = null;\\n    if (type === \\\"PACK\\\") {\\n      if (\\n        typeof record.parcelCode !== \\\"string\\\" ||\\n        record.parcelCode.length === 0\\n      ) {\\n        throw new Error(\\\"PACK.parcelCode must be a non-empty string\\\");\\n      }\\n      if (\\n        typeof record.weightGrams !== \\\"number\\\" ||\\n        !Number.isInteger(record.weightGrams) ||\\n        record.weightGrams <= 0\\n      ) {\\n        throw new Error(\\\"PACK.weightGrams must be a positive integer\\\");\\n      }\\n      code = record.parcelCode;\\n      weight = record.weightGrams;\\n    }\\n\\n    const allowed =\\n      (this.state === \\\"EMPTY\\\" && type === \\\"PACK\\\") ||\\n      (this.state === \\\"PACKED\\\" && type === \\\"DISPATCH\\\") ||\\n      (this.state === \\\"DISPATCHED\\\" && type === \\\"DELIVER\\\") ||\\n      (this.state === \\\"DELIVERED\\\" && type === \\\"RESET\\\");\\n\\n    if (!allowed) {\\n      throw new Error(`invalid transition: ${this.state} -> ${type}`);\\n    }\\n\\n    if (type === \\\"PACK\\\") {\\n      this.parcelCode = code;\\n      this.weightGrams = weight;\\n      this.state = \\\"PACKED\\\";\\n    } else if (type === \\\"DISPATCH\\\") {\\n      this.state = \\\"DISPATCHED\\\";\\n    } else if (type === \\\"DELIVER\\\") {\\n      this.state = \\\"DELIVERED\\\";\\n    } else {\\n      this.state = \\\"EMPTY\\\";\\n      this.parcelCode = null;\\n      this.weightGrams = null;\\n    }\\n\\n    return this.view();\\n  }\\n\\n  view(): ParcelView {\\n    return {\\n      state: this.state,\\n      parcelCode: this.parcelCode,\\n      weightGrams: this.weightGrams,\\n    };\\n  }\\n}\\n\",\"known_bad_label\":\"Treats a whitespace-only parcel code as valid malformed input because it checks raw length without trimming.\"},{\"id\":\"cap-v2-stateful_workflows-typescript-generation-02\",\"problem\":\"Create one complete TypeScript source file implementing this exact public API:\\n\\n```typescript\\nexport type ReviewState = \\\"IDLE\\\" | \\\"REVIEWING\\\" | \\\"ACCEPTED\\\" | \\\"REJECTED\\\";\\n\\nexport interface ReviewView {\\n  state: ReviewState;\\n  documentId: string | null;\\n  decisionNote: string | null;\\n}\\n\\nexport class ReviewCycle {\\n  apply(command: unknown): ReviewView;\\n  view(): ReviewView;\\n}\\n```\\n\\nA new cycle is `IDLE`. It supports these commands:\\n\\n- `{ type: \\\"START\\\", documentId }`: moves `IDLE` to `REVIEWING`; `documentId` must be a string containing a non-whitespace character.\\n- `{ type: \\\"DECIDE\\\", approved, note }`: moves `REVIEWING` to `ACCEPTED` when `approved` is `true`, otherwise to `REJECTED`. `approved` must be a boolean, and `note` must be a string containing a non-whitespace character.\\n- `{ type: \\\"CLEAR\\\" }`: moves either terminal state back to `IDLE` and clears stored fields.\\n\\nA command must be a non-null, non-array object. Validate all fields for its command type before checking whether the transition is allowed. Throw these exact malformed-input errors:\\n\\n- `command must be an object`\\n- `type must be START, DECIDE, or CLEAR`\\n- `START.documentId must be a non-empty string`\\n- `DECIDE.approved must be a boolean`\\n- `DECIDE.note must be a non-empty string`\\n\\nA valid command in an invalid state throws `invalid transition: <state> -> <type>`. A failed call must not alter state or stored fields. Successful calls and `view()` return the current view. Additional object properties are ignored. Use no filesystem, network, clock, randomness, packages, or frameworks.\",\"reference_code\":\"export type ReviewState = \\\"IDLE\\\" | \\\"REVIEWING\\\" | \\\"ACCEPTED\\\" | \\\"REJECTED\\\";\\n\\nexport interface ReviewView {\\n  state: ReviewState;\\n  documentId: string | null;\\n  decisionNote: string | null;\\n}\\n\\ntype InputRecord = Record<string, unknown>;\\n\\nfunction requireRecord(command: unknown): InputRecord {\\n  if (typeof command !== \\\"object\\\" || command === null || Array.isArray(command)) {\\n    throw new Error(\\\"command must be an object\\\");\\n  }\\n  return command as InputRecord;\\n}\\n\\nexport class ReviewCycle {\\n  private state: ReviewState = \\\"IDLE\\\";\\n  private documentId: string | null = null;\\n  private decisionNote: string | null = null;\\n\\n  apply(command: unknown): ReviewView {\\n    const record = requireRecord(command);\\n    const type = record.type;\\n    if (type !== \\\"START\\\" && type !== \\\"DECIDE\\\" && type !== \\\"CLEAR\\\") {\\n      throw new Error(\\\"type must be START, DECIDE, or CLEAR\\\");\\n    }\\n\\n    let nextDocumentId: string | null = null;\\n    let approved: boolean | null = null;\\n    let note: string | null = null;\\n\\n    if (type === \\\"START\\\") {\\n      if (\\n        typeof record.documentId !== \\\"string\\\" ||\\n        record.documentId.trim().length === 0\\n      ) {\\n        throw new Error(\\\"START.documentId must be a non-empty string\\\");\\n      }\\n      nextDocumentId = record.documentId;\\n    } else if (type === \\\"DECIDE\\\") {\\n      if (typeof record.approved !== \\\"boolean\\\") {\\n        throw new Error(\\\"DECIDE.approved must be a boolean\\\");\\n      }\\n      if (typeof record.note !== \\\"string\\\" || record.note.trim().length === 0) {\\n        throw new Error(\\\"DECIDE.note must be a non-empty string\\\");\\n      }\\n      approved = record.approved;\\n      note = record.note;\\n    }\\n\\n    const allowed =\\n      (this.state === \\\"IDLE\\\" && type === \\\"START\\\") ||\\n      (this.state === \\\"REVIEWING\\\" && type === \\\"DECIDE\\\") ||\\n      ((this.state === \\\"ACCEPTED\\\" || this.state === \\\"REJECTED\\\") &&\\n        type === \\\"CLEAR\\\");\\n\\n    if (!allowed) {\\n      throw new Error(`invalid transition: ${this.state} -> ${type}`);\\n    }\\n\\n    if (type === \\\"START\\\") {\\n      this.documentId = nextDocumentId;\\n      this.decisionNote = null;\\n      this.state = \\\"REVIEWING\\\";\\n    } else if (type === \\\"DECIDE\\\") {\\n      this.decisionNote = note;\\n      this.state = approved === true ? \\\"ACCEPTED\\\" : \\\"REJECTED\\\";\\n    } else {\\n      this.state = \\\"IDLE\\\";\\n      this.documentId = null;\\n      this.decisionNote = null;\\n    }\\n\\n    return this.view();\\n  }\\n\\n  view(): ReviewView {\\n    return {\\n      state: this.state,\\n      documentId: this.documentId,\\n      decisionNote: this.decisionNote,\\n    };\\n  }\\n}\\n\",\"known_bad_code\":\"export type ReviewState = \\\"IDLE\\\" | \\\"REVIEWING\\\" | \\\"ACCEPTED\\\" | \\\"REJECTED\\\";\\n\\nexport interface ReviewView {\\n  state: ReviewState;\\n  documentId: string | null;\\n  decisionNote: string | null;\\n}\\n\\ntype InputRecord = Record<string, unknown>;\\n\\nfunction requireRecord(command: unknown): InputRecord {\\n  if (typeof command !== \\\"object\\\" || command === null || Array.isArray(command)) {\\n    throw new Error(\\\"command must be an object\\\");\\n  }\\n  return command as InputRecord;\\n}\\n\\nexport class ReviewCycle {\\n  private state: ReviewState = \\\"IDLE\\\";\\n  private documentId: string | null = null;\\n  private decisionNote: string | null = null;\\n\\n  apply(command: unknown): ReviewView {\\n    const record = requireRecord(command);\\n    const type = record.type;\\n    if (type !== \\\"START\\\" && type !== \\\"DECIDE\\\" && type !== \\\"CLEAR\\\") {\\n      throw new Error(\\\"type must be START, DECIDE, or CLEAR\\\");\\n    }\\n\\n    let nextDocumentId: string | null = null;\\n    let approved: boolean | null = null;\\n    let note: string | null = null;\\n\\n    if (type === \\\"START\\\") {\\n      if (\\n        typeof record.documentId !== \\\"string\\\" ||\\n        record.documentId.trim().length === 0\\n      ) {\\n        throw new Error(\\\"START.documentId must be a non-empty string\\\");\\n      }\\n      nextDocumentId = record.documentId;\\n    } else if (type === \\\"DECIDE\\\") {\\n      if (!(\\\"approved\\\" in record)) {\\n        throw new Error(\\\"DECIDE.approved must be a boolean\\\");\\n      }\\n      if (typeof record.note !== \\\"string\\\" || record.note.trim().length === 0) {\\n        throw new Error(\\\"DECIDE.note must be a non-empty string\\\");\\n      }\\n      approved = Boolean(record.approved);\\n      note = record.note;\\n    }\\n\\n    const allowed =\\n      (this.state === \\\"IDLE\\\" && type === \\\"START\\\") ||\\n      (this.state === \\\"REVIEWING\\\" && type === \\\"DECIDE\\\") ||\\n      ((this.state === \\\"ACCEPTED\\\" || this.state === \\\"REJECTED\\\") &&\\n        type === \\\"CLEAR\\\");\\n\\n    if (!allowed) {\\n      throw new Error(`invalid transition: ${this.state} -> ${type}`);\\n    }\\n\\n    if (type === \\\"START\\\") {\\n      this.documentId = nextDocumentId;\\n      this.decisionNote = null;\\n      this.state = \\\"REVIEWING\\\";\\n    } else if (type === \\\"DECIDE\\\") {\\n      this.decisionNote = note;\\n      this.state = approved === true ? \\\"ACCEPTED\\\" : \\\"REJECTED\\\";\\n    } else {\\n      this.state = \\\"IDLE\\\";\\n      this.documentId = null;\\n      this.decisionNote = null;\\n    }\\n\\n    return this.view();\\n  }\\n\\n  view(): ReviewView {\\n    return {\\n      state: this.state,\\n      documentId: this.documentId,\\n      decisionNote: this.decisionNote,\\n    };\\n  }\\n}\\n\",\"known_bad_label\":\"Accepts any present `approved` value and coerces it to boolean instead of rejecting non-boolean malformed input.\"},{\"id\":\"cap-v2-stateful_workflows-typescript-repair-01\",\"problem\":\"Repair the source below and return one complete TypeScript source file.\\n\\nThe file must preserve this public API:\\n\\n```typescript\\nexport type TaskState = \\\"QUEUED\\\" | \\\"RUNNING\\\" | \\\"COMPLETED\\\";\\n\\nexport class TaskScheduler {\\n  enqueue(id: string, priority: number): void;\\n  startNext(): string | undefined;\\n  complete(id: string): void;\\n  getState(id: string): TaskState | undefined;\\n}\\n```\\n\\nCallers provide non-empty unique IDs and finite priorities. `enqueue` creates a `QUEUED` task. `startNext` selects the queued task with the greatest priority, changes it to `RUNNING`, and returns its ID. Among equal-priority tasks it must select in original enqueue order, regardless of their IDs or of earlier task completions. It returns `undefined` when nothing is queued. `complete` changes a `RUNNING` task to `COMPLETED`; otherwise it throws `Task is not running: <id>` without changing any task. `getState` reports the current state.\\n\\nDo not use filesystem, network, clock, randomness, packages, or frameworks.\\n\\nThe current implementation violates the equal-priority ordering rule:\\n\\n```typescript\\nexport type TaskState = \\\"QUEUED\\\" | \\\"RUNNING\\\" | \\\"COMPLETED\\\";\\n\\ninterface TaskRecord {\\n  id: string;\\n  priority: number;\\n  order: number;\\n  state: TaskState;\\n}\\n\\nexport class TaskScheduler {\\n  private readonly tasks = new Map<string, TaskRecord>();\\n  private nextOrder = 0;\\n\\n  enqueue(id: string, priority: number): void {\\n    this.tasks.set(id, {\\n      id,\\n      priority,\\n      order: this.nextOrder++,\\n      state: \\\"QUEUED\\\",\\n    });\\n  }\\n\\n  startNext(): string | undefined {\\n    const queued = [...this.tasks.values()].filter(\\n      (task) => task.state === \\\"QUEUED\\\",\\n    );\\n    queued.sort(\\n      (left, right) =>\\n        right.priority - left.priority || left.id.localeCompare(right.id),\\n    );\\n\\n    const selected = queued[0];\\n    if (selected === undefined) {\\n      return undefined;\\n    }\\n    selected.state = \\\"RUNNING\\\";\\n    return selected.id;\\n  }\\n\\n  complete(id: string): void {\\n    const task = this.tasks.get(id);\\n    if (task === undefined || task.state !== \\\"RUNNING\\\") {\\n      throw new Error(`Task is not running: ${id}`);\\n    }\\n    task.state = \\\"COMPLETED\\\";\\n  }\\n\\n  getState(id: string): TaskState | undefined {\\n    return this.tasks.get(id)?.state;\\n  }\\n}\\n```\",\"reference_code\":\"export type TaskState = \\\"QUEUED\\\" | \\\"RUNNING\\\" | \\\"COMPLETED\\\";\\n\\ninterface TaskRecord {\\n  id: string;\\n  priority: number;\\n  order: number;\\n  state: TaskState;\\n}\\n\\nexport class TaskScheduler {\\n  private readonly tasks = new Map<string, TaskRecord>();\\n  private nextOrder = 0;\\n\\n  enqueue(id: string, priority: number): void {\\n    this.tasks.set(id, {\\n      id,\\n      priority,\\n      order: this.nextOrder++,\\n      state: \\\"QUEUED\\\",\\n    });\\n  }\\n\\n  startNext(): string | undefined {\\n    const queued = [...this.tasks.values()].filter(\\n      (task) => task.state === \\\"QUEUED\\\",\\n    );\\n    queued.sort(\\n      (left, right) =>\\n        right.priority - left.priority || left.order - right.order,\\n    );\\n\\n    const selected = queued[0];\\n    if (selected === undefined) {\\n      return undefined;\\n    }\\n    selected.state = \\\"RUNNING\\\";\\n    return selected.id;\\n  }\\n\\n  complete(id: string): void {\\n    const task = this.tasks.get(id);\\n    if (task === undefined || task.state !== \\\"RUNNING\\\") {\\n      throw new Error(`Task is not running: ${id}`);\\n    }\\n    task.state = \\\"COMPLETED\\\";\\n  }\\n\\n  getState(id: string): TaskState | undefined {\\n    return this.tasks.get(id)?.state;\\n  }\\n}\\n\",\"known_bad_code\":\"export type TaskState = \\\"QUEUED\\\" | \\\"RUNNING\\\" | \\\"COMPLETED\\\";\\n\\ninterface TaskRecord {\\n  id: string;\\n  priority: number;\\n  order: number;\\n  state: TaskState;\\n}\\n\\nexport class TaskScheduler {\\n  private readonly tasks = new Map<string, TaskRecord>();\\n  private nextOrder = 0;\\n\\n  enqueue(id: string, priority: number): void {\\n    this.tasks.set(id, {\\n      id,\\n      priority,\\n      order: this.nextOrder++,\\n      state: \\\"QUEUED\\\",\\n    });\\n  }\\n\\n  startNext(): string | undefined {\\n    const queued = [...this.tasks.values()].filter(\\n      (task) => task.state === \\\"QUEUED\\\",\\n    );\\n    queued.sort(\\n      (left, right) =>\\n        right.priority - left.priority || left.id.localeCompare(right.id),\\n    );\\n\\n    const selected = queued[0];\\n    if (selected === undefined) {\\n      return undefined;\\n    }\\n    selected.state = \\\"RUNNING\\\";\\n    return selected.id;\\n  }\\n\\n  complete(id: string): void {\\n    const task = this.tasks.get(id);\\n    if (task === undefined || task.state !== \\\"RUNNING\\\") {\\n      throw new Error(`Task is not running: ${id}`);\\n    }\\n    task.state = \\\"COMPLETED\\\";\\n  }\\n\\n  getState(id: string): TaskState | undefined {\\n    return this.tasks.get(id)?.state;\\n  }\\n}\\n\",\"known_bad_label\":\"Orders equal-priority queued tasks lexicographically by ID instead of preserving their enqueue order.\"}]}"}}
