{"items":[{"id":"cap-v2-stateful_workflows-typescript-repair-02","test_code":"import { ResourceWorkflow } from "./solution";

function assertEqual(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, received ${actualJson}`);
  }
}

function assertJobNotRunning(action: () => unknown, message: string): void {
  let caught: unknown;
  try {
    action();
  } catch (error) {
    caught = error;
  }
  if (!(caught instanceof Error) || caught.message !== "Job is not running") {
    throw new Error(`${message}: expected Error(\"Job is not running\")`);
  }
}

const workflow = new ResourceWorkflow(10);
assertDeepEqual(
  workflow.snapshot(),
  { availableUnits: 10, running: null, jobs: [] },
  "new workflow"
);

const firstSnapshot = workflow.submit({ id: "first", priority: 0, units: 4 });
assertDeepEqual(
  firstSnapshot,
  {
    availableUnits: 6,
    running: "first",
    jobs: [{ id: "first", state: "running" }]
  },
  "first submitted job starts immediately"
);

workflow.submit({ id: "older-tie", priority: 5, units: 2 });
workflow.submit({ id: "highest", priority: 9, units: 7 });
workflow.submit({ id: "newer-tie", priority: 5, units: 3 });

const beforeInvalidCompletion = workflow.snapshot();
assertJobNotRunning(
  () => workflow.complete("older-tie"),
  "queued jobs cannot complete"
);
assertDeepEqual(
  workflow.snapshot(),
  beforeInvalidCompletion,
  "failed transition does not mutate the workflow"
);

const afterFirst = workflow.complete("first");
assertDeepEqual(
  afterFirst,
  {
    availableUnits: 3,
    running: "highest",
    jobs: [
      { id: "first", state: "completed" },
      { id: "older-tie", state: "queued" },
      { id: "highest", state: "running" },
      { id: "newer-tie", state: "queued" }
    ]
  },
  "greatest-priority queued job starts after completion"
);

const afterHighestRollback = workflow.rollback("highest");
assertDeepEqual(
  afterHighestRollback,
  {
    availableUnits: 8,
    running: "older-tie",
    jobs: [
      { id: "first", state: "completed" },
      { id: "older-tie", state: "running" },
      { id: "highest", state: "rolled_back" },
      { id: "newer-tie", state: "queued" }
    ]
  },
  "priority ties use original submission order"
);

workflow.complete("older-tie");
assertEqual(workflow.snapshot().running, "newer-tie", "remaining tied job starts next");
assertEqual(workflow.snapshot().availableUnits, 7, "next job reserves its units");

const finalSnapshot = workflow.rollback("newer-tie");
assertDeepEqual(
  finalSnapshot,
  {
    availableUnits: 10,
    running: null,
    jobs: [
      { id: "first", state: "completed" },
      { id: "older-tie", state: "completed" },
      { id: "highest", state: "rolled_back" },
      { id: "newer-tie", state: "rolled_back" }
    ]
  },
  "finishing the final job restores full capacity"
);

assertJobNotRunning(() => workflow.complete("first"), "completed job cannot complete again");
assertJobNotRunning(() => workflow.rollback("missing"), "unknown job cannot roll back");
assertDeepEqual(
  firstSnapshot,
  {
    availableUnits: 6,
    running: "first",
    jobs: [{ id: "first", state: "running" }]
  },
  "previously returned snapshots remain stable"
);

const boundary = new ResourceWorkflow(3);
assertEqual(
  boundary.submit({ id: "all", priority: -10, units: 3 }).availableUnits,
  0,
  "a job may reserve the full capacity"
